import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        char[] s = next().toCharArray();
        int m = nextInt();
        int n = s.length;
        long[] diff = new long[n + 1];
        for (int i = 0; i < m; i++) {
            int k = nextInt();
            diff[0]++;
            diff[k]--;
        }
        long count = 0;
        for (int i = 0; i < n; i++) {
            count += diff[i];
            s[i] = (char) ('a' + (s[i] - 'a' + count) % 26);
        }
        System.out.println(new String(s));
    }
}

package main

import (
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := []byte(string(next()))
	m := int(nextInt())
	n := len(s)
	diff := make([]int64, n+1)
	for i := 0; i < m; i++ {
		k := nextInt()
		diff[0]++
		diff[k]--
	}
	var count int64
	for i := 0; i < n; i++ {
		count += diff[i]
		s[i] = byte('a' + (int64(s[i]-'a')+count)%26)
	}
	os.Stdout.Write(append(s, '\n'))
}
